O=r'o(?:nis|ni|nem|ne|nes|num|nibus)?'; IS=r'(?:is|i|em|e|es|ium|ibus)'
def us(s):return r'\b'+s+US+r'\b'
def ua(s):return r'\b'+s+UA+r'\b'
def a(s):return r'\b'+s+A+r'\b'
def tor(s):return r'\b'+s+OR+r'\b'
def trix(s):return r'\b'+s+RIX+r'\b'
